const r = $input.first().json.report || {};
const projects = Array.isArray(r.projects) ? r.projects : [];

const PHASE_RANK = { intake:0, briefing_done:1, design_done:2, analysis_done:3, costs_done:4, trades_done:5, proposal_done:6, approved:7, planning_done:8 };

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function calcGrade(p) {
  const rank = PHASE_RANK[p.current_phase] || 0;
  const checks = [
    { critical: true,  applicable: true,                 met: p.briefing_approved },
    { critical: true,  applicable: rank >= 1,            met: p.design_selected },
    { critical: true,  applicable: rank >= 3,            met: p.cost_breakdown_ok },
    { critical: true,  applicable: rank >= 6,            met: p.encargo_signed },
    { critical: true,  applicable: rank >= 6,            met: p.permits_approved > 0 },
    { critical: true,  applicable: rank >= 5,            met: p.safety_confirmed },
    { critical: true,  applicable: p.has_handover,       met: p.acta_recepcion },
    { critical: true,  applicable: p.has_handover,       met: p.aftercare_urgent === 0 },
    { critical: true,  applicable: true,                 met: p.gdpr_consent },
    { critical: false, applicable: rank >= 7,            met: p.qc_blocked === 0 },
    { critical: false, applicable: true,                 met: p.pathology_critical === 0 }
  ];
  const applicable = checks.filter(c => c.applicable);
  const failed = applicable.filter(c => !c.met);
  const critical = failed.filter(c => c.critical);
  const score = applicable.length === 0 ? 100 : Math.round(100 * (applicable.length - failed.length) / applicable.length);
  const grade = critical.length > 0 ? 'D' : failed.length > 2 ? 'C' : failed.length > 0 ? 'B' : 'A';
  return { score, grade, critical_count: critical.length, failed_count: failed.length };
}

const enriched = projects.map(p => ({ ...p, ...calcGrade(p) }));
enriched.sort((a, b) => (a.score || 0) - (b.score || 0));

const grades = { A: 0, B: 0, C: 0, D: 0 };
let totalCritical = 0;
let totalAftercareUrgent = 0;
let totalPathologyCritical = 0;
for (const p of enriched) {
  grades[p.grade] = (grades[p.grade] || 0) + 1;
  totalCritical += p.critical_count;
  totalAftercareUrgent += p.aftercare_urgent || 0;
  totalPathologyCritical += p.pathology_critical || 0;
}

const gradeColor = { A:'#27ae60', B:'#f1c40f', C:'#e67e22', D:'#e74c3c' };

function icon(b) { return b ? '<span style="color:#27ae60">+</span>' : '<span style="color:#c00">-</span>'; }
function num(n, danger) { return n > 0 ? `<span style="color:${danger ? '#c00' : '#666'};font-weight:600">${n}</span>` : '<span style="color:#27ae60">0</span>'; }

const rows = enriched.map(p => `<tr style="background:${p.grade === 'D' ? '#fee' : (p.grade === 'C' ? '#fff8e0' : '#fff')}">
  <td><a href="/webhook/admin-project?project_id=${esc(p.project_id)}" style="color:#1f2937;text-decoration:none;font-weight:600">${esc(p.project_name)}</a></td>
  <td><span style="background:${gradeColor[p.grade]};color:white;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:bold">${p.grade}</span> ${p.score}</td>
  <td>${esc(p.current_phase)}</td>
  <td style="text-align:center">${icon(p.briefing_approved)}</td>
  <td style="text-align:center">${icon(p.design_selected)}</td>
  <td style="text-align:center">${icon(p.cost_breakdown_ok)}</td>
  <td style="text-align:center">${icon(p.encargo_signed)}</td>
  <td style="text-align:center">${p.permits_approved > 0 ? '<span style="color:#27ae60">' + p.permits_approved + '</span>' : icon(false)}</td>
  <td style="text-align:center">${icon(p.safety_confirmed)}</td>
  <td style="text-align:center">${icon(p.gdpr_consent)}</td>
  <td style="text-align:center">${num(p.aftercare_urgent, true)}</td>
  <td style="text-align:center">${num(p.pathology_critical, true)}</td>
  <td style="text-align:center">${num(p.qc_blocked, true)}</td>
</tr>`).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Compliance Overview - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1300px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  .cards{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:12px;text-align:center}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase;letter-spacing:.5px}
  .card .v{font-size:22px;font-weight:600}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:12px}
  th,td{padding:6px 8px;border-bottom:1px solid #eee;text-align:left;vertical-align:middle}
  th{background:#f0f0f3;font-weight:600;font-size:10px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:1100px){.cards{grid-template-columns:repeat(4,1fr)}}
</style></head><body>
<h1>Compliance Overview - ArquitAI</h1>
<p class="sub">Snapshot inmediato (sin LLM): ${enriched.length} proyectos activos. Para audit detallado por proyecto: <code>POST /webhook/audit-project</code>. Audit semanal automatico: domingos 08:00.</p>
<div class="cards">
  <div class="card"><h3>Total</h3><div class="v">${enriched.length}</div></div>
  <div class="card"><h3>Grade A</h3><div class="v" style="color:${gradeColor.A}">${grades.A}</div></div>
  <div class="card"><h3>Grade B</h3><div class="v" style="color:${gradeColor.B}">${grades.B}</div></div>
  <div class="card"><h3>Grade C</h3><div class="v" style="color:${gradeColor.C}">${grades.C}</div></div>
  <div class="card"><h3>Grade D</h3><div class="v" style="color:${gradeColor.D}">${grades.D}</div></div>
  <div class="card"><h3>Aftercare urg</h3><div class="v" style="color:${totalAftercareUrgent > 0 ? '#c00' : '#27ae60'}">${totalAftercareUrgent}</div></div>
  <div class="card"><h3>Pathology crit</h3><div class="v" style="color:${totalPathologyCritical > 0 ? '#c00' : '#27ae60'}">${totalPathologyCritical}</div></div>
</div>
<table>
  <thead><tr><th>proyecto</th><th>grade</th><th>fase</th><th>brief</th><th>diseno</th><th>costes</th><th>encargo</th><th>permit</th><th>safety</th><th>gdpr</th><th>aftc</th><th>patol</th><th>qc</th></tr></thead>
  <tbody>${rows || '<tr><td colspan="13" style="text-align:center;color:#888;padding:24px">Sin proyectos activos</td></tr>'}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
